My suggestion:
1. Add a host-memory register
2. add register selector in interface.py
3. pin_mmap_region has no platform branches. It keeps the chunk/rollback loop and runs it through the registrar:
```
class HostMemoryRegistrar(ABC):
    """Registers host memory so the device can DMA directly into it."""

    # Bound per-call size to avoid driver limits on large registrations.
    max_chunk_bytes: int = 64 * 1024**3

    @classmethod
    def is_available(cls) -> bool:
        return True

    @abstractmethod
    def register(self, ptr: int, size: int) -> bool: ...

    @abstractmethod
    def unregister(self, ptr: int) -> bool: ...


class CudaHostRegistrar(HostMemoryRegistrar):
    ...

class XpuHostRegistrar(HostMemoryRegistrar):
    ...

```
```
def pin_mmap_region(region, registrar: HostMemoryRegistrar) -> None:
    rows_per_chunk = max(registrar.max_chunk_bytes // region._row_stride, 1)
    ...
    for offset in range(0, total_size, chunk_size):
        try:
            ok = registrar.register(address, size)
        except Exception:
            logger.warning(..., exc_info=True)
            ok = False
        if not ok:
            for a in reversed(addresses):
                registrar.unregister(a)  # best-effort, logged
            return
        addresses.append(address)
    region.registrar = registrar
    region.pinned_addresses.extend(addresses)
    region.is_pinned = True

```

